files.gemini-extension.json:
{
  "name": "grafana",
  "version": "0.7.0",
  "mcpServers": {
    "grafana": {
      "command": "${extensionPath}${/}mcp-grafana"
    }
  },
  "settings": [
    {
      "name": "Grafana URL",
      "description": "The base URL of your Grafana instance (e.g., https://grafana.example.com)",
      "envVar": "GRAFANA_URL",
      "required": true
    },
    {
      "name": "Service Account Token",
      "description": "Your Grafana Service Account Token (glsa_...)",
      "envVar": "GRAFANA_SERVICE_ACCOUNT_TOKEN",
      "required": true,
      "sensitive": true
    },
    {
      "name": "Organization ID",
      "description": "The Grafana Organization ID to use",
      "envVar": "GRAFANA_ORG_ID"
    }
  ]
}

files.renovate.json:
{
    "ignorePresets": [
        "github>grafana/grafana-renovate-config//presets/base",
        "github>grafana/grafana-renovate-config//presets/automerge",
        "github>grafana/grafana-renovate-config//presets/labels",
        "github>grafana/grafana-renovate-config//presets/npm"
    ],
    "extends": [
        "config:best-practices",
        ":disableDependencyDashboard",
        ":preserveSemverRanges",
        "schedule:weekly",
        "group:allNonMajor",
        "github>grafana/grafana-renovate-config//presets/plugin-ci-workflows"
    ],
    "minimumReleaseAge": "14 days",
    "rebaseWhen": "conflicted",
    "separateMajorMinor": true,
    "packageRules": [
        {
            "description": "Group all non-major updates into a single PR",
            "matchUpdateTypes": ["minor", "patch", "pin", "digest"],
            "groupName": "all non-major dependencies"
        },
        {
            "description": "Major updates get individual PRs for careful review",
            "matchUpdateTypes": ["major"],
            "groupName": null
        },
        {
            "description": "Group Docker digest updates and automerge",
            "matchDatasources": ["docker"],
            "matchUpdateTypes": ["digest"],
            "groupName": "docker digest updates",
            "automerge": true
        },
        {
            "description": "Automerge patch-level updates",
            "matchUpdateTypes": ["patch", "pin"],
            "automerge": true
        }
    ]
}

